export function GhostButton({ children }: { children: React.ReactNode }) {
  return (
    <button className="group relative inline-flex items-center justify-center overflow-hidden rounded-lg border border-stone-300 px-5 py-2.5 text-sm font-medium text-stone-700 transition-colors duration-150 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:focus-visible:outline-emerald-400 active:scale-[0.97] dark:border-stone-600 dark:text-stone-200">
      <span
        aria-hidden
        className="absolute inset-0 origin-left scale-x-0 bg-amber-700 transition-transform duration-300 ease-out group-hover:scale-x-100 motion-reduce:transition-none dark:bg-amber-700"
      />
      <span className="relative transition-colors duration-150 group-hover:text-white">
        {children}
      </span>
    </button>
  );
}
